"""Render preliminary decisions and a separate non-normative Product B."""
from pathlib import Path
import runpy,json
HERE=Path(__file__).resolve().parent
D=runpy.run_path(str(HERE/'decisions.py'))['D'];S=json.loads((HERE/'semantic-requirements.json').read_text())
for d in D:d['requirements']=[c['requirement_id'] for c in S['requirements'] if c['gap']==d['id'].replace('DEC-','')];d['code_and_tests']='See per-requirement implementation/evidence refs in contract-reconciliation.json; not authority.'
(HERE/'unresolved-decisions.json').write_text(json.dumps({'status':'PRELIMINARY_NOT_APPROVED','recommended_gate':'HOLD_INSUFFICIENT_AUTHORITY','do_not_resolve_recoverable_source_by_policy':True,'decisions':D},ensure_ascii=False,indent=2)+'\n')
lines=['# UNRESOLVED_DECISIONS — F5-D','','**DRAFT / UNAPPROVED / NON-NORMATIVE.** DEC-G06 is resolved in scope, not a new semantic choice.','', 'Norma, código, pruebas y decisión se separan por contrato en [matriz](contract-reconciliation.json). No se adopta una recomendación por estar ya implementada. La fuente externa identificada tiene prioridad sobre elegir una política nueva.','']
for d in D:
 lines+=['',f'<a id="{d["id"].lower()}"></a>',f'## {d["id"]} — {d["status"]}','',f'Prioridad: {d["priority"]}. Contratos: '+', '.join(d['requirements'])+'.']
 for field,label in [('norma','NORMA disponible'),('missing_information','Información ausente'),('technically_valid_alternatives','Alternativas'),('observable_differences','Diferencias observables'),('recommendation','Recomendación'),('evidence_that_refutes_recommendation','Qué la refutaría'),('impact_on_code_and_tests','Impacto potencial'),('normative_approval','Aprobación')]:
  value=d[field];value='; '.join(value) if isinstance(value,list) else value;lines+=['',f'**{label}:** {value}']
 lines+=['','**Compatibilidad aprobada:** ninguna propuesta revoca D-01, INIT-004 ni altera contratos determinados. Ingeniería autorizada de implementación no se presenta como fuente histórica completa.','', '**CÓDIGO/PRUEBAS:** '+d['code_and_tests']]
(HERE/'UNRESOLVED_DECISIONS.md').write_text('\n'.join(lines)+'\n')
# Only new proposals appear here. It is NOT a second consolidated source authority.
P=[
 ('P01','DEC-G01','Financiación y orden energético','Sujeto a fuente externa; escoger coste previo evita financiar el movimiento con la recompensa de destino y permite explicar el presupuesto energético.','Para una acción aceptada, verificar disponibilidad antes del efecto; calcular energía tras coste y después aplicar el efecto de entrada, canonicalizando cada operación binary64. WAIT no reentra efectos. Un rechazo no cobra coste ni cambia WORLD. energy_delta es canonicalize_binary64(energía_final−energía_previa).','La disponibilidad/WAIT/delta son selección observable pendiente; no atribuir esta redacción al manuscrito histórico.'),
 ('P02','DEC-G01','ActionResult portable','Un resultado mínimo estable puede comunicar ejecución y causa sin contexto redundante; la clasificación exacta es elección contractual.','Si se adopta esta alternativa: ActionResult cerrado={validity,reason,energy_delta,events}; VALID/NONE al ejecutar, INVALID para entidad inactiva/borde/bloqueo, FAILED/INSUFFICIENT_ENERGY para no pagar. Eventos crudos y delta finito canonicalizado.','Enums/clasificación son propuesta nueva condicionada, no norma original. Alternativas deben evaluarse con consumidores y fuentes.'),
 ('P03','DEC-G02','Regeneración binaria','Reposición inmediata es una alternativa simple sin estado temporal ni RNG adicionales, si la fuente no determina otra regla.','Si se adopta: al ejecutar regenerate_resources, stock0 pasa a1 si resource_regeneration>0; tasa0 conserva stock y stock1 permanece1; no crear recursos ni cambiar entidad/tiempo/lifecycle/RNG ni emitir eventos.','No se impone esta fórmula por aparecer en legacy; unidad/timing pueden estar fijados en fuente externa.'),
 ('P04','DEC-G03','Proyección y subregistros','Evitar fuga y distinguir una etiqueta ausente de un enum de acción inventado. La ABI debe fijarse antes de comparar motores.','Si se adopta forma estable: proyección de acción previa con validity/reason=null cuando ocultos, events=[] cuando ocultos y energy_delta=+0 cuando oculto. Habilitados preservan valores. La proyección no es un ActionResult crudo. Definir subesquemas self/local_view por revisión separada contra §16 recuperado antes de fijar ABI completa.','Texto no es una definición completa de Observation y no declara cerrada G03.'),
 ('P05','DEC-G04','Orden de eventos operacionales','El movimiento antecede causalmente al efecto de entrada; una activación puede ser un hecho aun con magnitud0.','Si la fuente no determina lo contrario y se aprueba esta alternativa: MOVE aceptado emite ENTITY_MOVED antes del efecto; consumo stock1→0 emite RESOURCE_CONSUMED, entrada en peligro emite HAZARD_TRIGGERED incluso con daño0. WAIT/rechazos no inventan efectos; apply_action nunca emite muerte.','Los tipos/esquemas recuperados permanecen; solo disparo/orden indeterminado se propone.'),
 ('P06','DEC-G05','Salidas de tick sin clase obligatoria','Snapshots y separación de eventos son observables; el contenedor interno de un mapa no debe limitar lenguajes.','Si se aprueba ABI F3A-P02/P03: TickResult={action_result,action_events,lifecycle_events}; ConfirmedTickResult={tick,world_state,action_result,action_events,lifecycle_events,termination}; snapshots independientes y action_events estructuralmente iguales a action_result.events; eventos crudos; tiempo/terminación según reglas vigentes. Mapas se interpretan semánticamente, sin exigir Map/instanceof de JS.','Requiere revisar campos frente a fuente externa; no modificar dominio D-01 ni WLS1.'),
 ('P07','DEC-G07','Capacidad operacional separada','Un radio semánticamente válido no garantiza materialización; el fallo no debe fingir configuración física inválida ni producir observación truncada.','Se propone decidir explícitamente el perfil de soporte y categoría de fallo operacional de observación antes de aceptación. Preservar radio uint32 y ausencia de mutación/RNG ante fallo; no fijar64MiB como ley física ni asignar un nuevo error_message sin autorización.','No es cláusula operacional completa: categoría/garantía requieren decisión tras recuperar fuente. No cambia arquitectura ni código ahora.'),
 ('P08','DEC-G09','Aceptación y referencias nuevas','Expectativas y suficiencia deben fijarse antes de contrastar implementaciones; un sustituto no puede omitir obligaciones desconocidas.','Solo después de cerrar contratos: revisar corpus/perfil y nuevos vectores por ID/versión/hash, con cálculo independiente. Una sustitución de T01–T280 o §37 requiere autorización normativa expresa; no renombrar PV-F5C como V2–V10 recuperados.','No se redacta ni aplica aquí un reemplazo aprobado de §37. La propuesta F5-C permanece sin aprobar.')]
md=['# NORMATIVE_CHANGE_PROPOSALS — Producto B','','**DRAFT / UNAPPROVED / NON-NORMATIVE. NO APLICAR.**','', 'Opciones condicionales para revisión, separadas del [Producto A](CONSOLIDATED_SPECIFICATION_CANDIDATE.md). La entrega de EXT-024/EXT-023 puede invalidarlas o volverlas innecesarias. No asignar versión por anticipado ni resolver por política una cláusula recuperable.','', 'No se propone cambiar física/arquitectura por mera conveniencia; la selección de resultados hoy indeterminados sería una precisión nueva, no equivalencia histórica demostrada.']
for key,dec,title,why,text,limit in P:
 md+=['',f'## {key} — {title}','',f'Dependencia: [{dec}](UNRESOLVED_DECISIONS.md#{dec.lower()}).','',f'Justificación independiente del código: {why}','',f'**Texto nuevo propuesto:** {text}','',f'**Límite:** {limit}']
md+=['','INIT-004 y D-01 no son propuestas nuevas: se consolidan con su alcance ya autorizado en Producto A. Las libertades internas de representación no requieren inventar un nuevo contrato físico.','', 'Cada eventual aprobación debe identificar cláusulas sustituidas, semántica elegida, compatibilidad, expectativas independientes y evidencia requerida. No cambiar tests existentes para convertir la selección en una falsa recuperación histórica.']
(HERE/'NORMATIVE_CHANGE_PROPOSALS.md').write_text('\n'.join(md)+'\n')

recon=json.loads((HERE/'contract-reconciliation.json').read_text())
recon['proposed_changes']=[{'id':key,'classification':'PROPOSED_CHANGE','decision_ref':dec,'title':title,'proposed_text':text,'justification_independent_of_code':why,'limits':limit,'authority':'NONE; conditional proposal, do not apply before recovery/review/express approval','product':'NORMATIVE_CHANGE_PROPOSALS.md'} for key,dec,title,why,text,limit in P]
(HERE/'contract-reconciliation.json').write_text(json.dumps(recon,ensure_ascii=False,indent=2)+'\n')
